const orig = require('./build/process_events_orig.js').processEvents;
const neu = require('./build/process_events_new.js').processEvents;

let seed = 12345;
function rnd() { seed = (seed * 1103515245 + 12345) & 0x7fffffff; return seed / 0x7fffffff; }
function ri(n) { return Math.floor(rnd() * n); }

const items = ['a', 'b', 'c'];
const types = ['order', 'cancel', 'ship', 'restock', 'expire', 'bogus'];

function genEvent(idsUsed) {
  const t = types[ri(types.length)];
  const e = { type: t };
  const pickId = () => idsUsed[ri(idsUsed.length)];
  if (t === 'order') {
    e.id = 'ord' + ri(1000);
    e.item = items[ri(items.length)];
    e.qty = 1 + ri(30);
    // inject occasional bad fields
    if (rnd() < 0.05) e.id = '';
    if (rnd() < 0.05) e.qty = ri(3) - 1;
  } else if (t === 'cancel') {
    e.id = pickId();
    if (rnd() < 0.05) e.id = '';
  } else if (t === 'ship') {
    e.id = pickId();
    if (rnd() < 0.1) delete e.qty; else e.qty = ri(40);
    if (rnd() < 0.05) e.qty = -3;
  } else if (t === 'restock') {
    e.item = items[ri(items.length)];
    e.qty = 1 + ri(20);
    if (rnd() < 0.05) e.qty = 0;
  } else if (t === 'expire') {
    e.id = pickId();
    if (rnd() < 0.05) e.id = '';
  }
  return e;
}

function genInput() {
  const idsUsed = ['nope1', 'nope2'];
  const stockCount = ri(5);
  const stock = {};
  for (let i = 0; i < stockCount; i++) {
    stock[items[ri(items.length)]] = ri(100);
    idsUsed.push('id' + ri(5000));
  }
  const events = [];
  const n = ri(40);
  for (let i = 0; i < n; i++) events.push(genEvent(idsUsed));
  const input = { stock, events };
  if (rnd() < 0.03) input.stock = 'bad';
  if (rnd() < 0.03) input.events = 'bad';
  if (rnd() < 0.03) { input.stock['x'] = 2.5; }
  if (rnd() < 0.03) { input.events.push(null); }
  if (rnd() < 0.03) { input.events.push({ type: 'order' }); }
  return input;
}

function norm(r) {
  return JSON.stringify(r);
}

let fails = 0;
for (let iter = 0; iter < 200000; iter++) {
  const input = genInput();
  const a = orig(JSON.parse(JSON.stringify(input)));
  const b = neu(JSON.parse(JSON.stringify(input)));
  if (norm(a) !== norm(b)) {
    fails++;
    console.log('MISMATCH iter', iter);
    console.log('input', JSON.stringify(input));
    console.log('orig', JSON.stringify(a));
    console.log('new ', JSON.stringify(b));
    if (fails > 5) break;
  }
}
console.log('done, fails =', fails);

